const body = $input.first().json.body || $input.first().json;
const isAr = (body.preferredLang || 'ar') === 'ar';

const confirmationSubject = isAr
  ? `تأكيد استلام الدفع وبدء توزيع سيرتك الذاتية (${body.customerReference})`
  : `Payment Confirmed — Starting Your CV Distribution (${body.customerReference})`;

const confirmationHtml = isAr
  ? `<div dir="rtl" style="font-family: Tahoma, Arial, sans-serif; line-height: 1.7;">
      <h2>مرحباً ${body.candidateName}،</h2>
      <p>شكراً لاختيارك منصة <strong>وظائف الخليج (WAZAYEF GCC)</strong>. تم تأكيد دفعتك بنجاح عبر EasyKash.</p>
      <p>بدأ نظامنا الآن في توزيع سيرتك الذاتية على <strong>${body.totalTargetCompanies} شركة موثقة</strong> في (${body.primaryCountry}).</p>
      <p>يمكنك متابعة حالة الإرسال لحظة بلحظة عبر لوحة التتبع الخاصة بك، وسنرسل لك إشعاراً آخر فور اكتمال العملية بالكامل.</p>
    </div>`
  : `<div style="font-family: Arial, sans-serif; line-height: 1.7;">
      <h2>Hello ${body.candidateName},</h2>
      <p>Thank you for choosing <strong>Wazayef GCC</strong>. Your EasyKash payment has been confirmed.</p>
      <p>Our engine has started distributing your CV to <strong>${body.totalTargetCompanies} verified companies</strong> in (${body.primaryCountry}).</p>
      <p>We will notify you via email as soon as the entire distribution batch is complete.</p>
    </div>`;

return [{
  json: {
    ...body,
    confirmationSubject,
    confirmationHtml
  }
}];
